def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')
    last_me, last_opp = history[-1]

    # Endgame: defect against likely exploiters, but stay cooperative if partner is clean
    if n >= 98:
        if opp_def > 0:
            return 'D'
        return 'C'

    # Track opponent's last-run of defections in reverse
    cons_opp_def = 0
    for a in reversed(opp):
        if a == 'D':
            cons_opp_def += 1
        else:
            break

    # Fast detection: pure/almost-pure defector -> defect
    if opp_def >= 6 and opp_def * 4 > n * 3:
        return 'D'

    # If opponent is very cooperative, preserve mutual cooperation but probe sparingly late
    if opp_def == 0:
        if n >= 85 and n % 11 == 0:
            return 'D'
        return 'C'
    if opp_def <= 2 and n >= 12:
        # Just had a defection; punish briefly then return to cooperation
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Recent defection ratio
    recent_len = 8 if n >= 8 else n
    recent = opp[-recent_len:]
    recent_def = sum(1 for a in recent if a == 'D')
    recent_c = recent_len - recent_def

    # If partner recently mostly cooperated, forgive isolated defections
    if recent_def <= 1:
        if last_opp == 'D' and cons_opp_def >= 2:
            return 'D'
        return 'C'

    # Opponent has been defecting recently: retaliate, but offer olive branches
    if recent_def * 2 >= recent_len:
        # If fully defecting for a while, match defection
        if cons_opp_def >= 4:
            return 'D'
        # If they just played C after some defections, reciprocate to rebuild trust
        if last_opp == 'C' and recent_c >= 2:
            return 'C'
        # Occasionally offer cooperation to reset, especially if mutual defection has happened
        if last_opp == 'D' and last_me == 'D':
            if rng.random() < 0.30:
                return 'C'
        return 'D'

    # Moderate defection rate: tit-for-tat with forgiveness
    if last_opp == 'D':
        # If we were also defecting, try an olive branch to break the cycle
        if last_me == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Punish a fresh defection once
        return 'D'

    # Opponent cooperated: cooperate to preserve mutual cooperation,
    # but if we've been exploited unusually much, be a bit more cautious
    if last_opp == 'C':
        if opp_def * 2 > n and last_me == 'D':
            return 'C'
        return 'C'

    return 'C'
